from functools import cmp_to_key
def comparar(a, b):
    if a[1] != b[1]:
        return b[1] - a[1]
    if a[0] < b[0]:
        return -1
    if a[0] > b[0]:
        return 1
    return 0
jogadores = [("Teo", 5), ("Ana", 8), ("Bia", 5)]
print(sorted(jogadores, key=cmp_to_key(comparar)))

